import{_ as r,c as i,o as l,ah as a}from"./chunks/framework.Ch_PcVtW.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART2/13/0_context_summary.md","filePath":"scripts/output/PART2/13/0_context_summary.md"}'),o={name:"scripts/output/PART2/13/0_context_summary.md"};function s(e,t,n,_,c,u){return l(),i("div",null,[...t[0]||(t[0]=[a('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇围绕SKY-HI在最大规模个人巡演《SKY-HI ARENA TOUR 2023 -BOSSDOM-》中的自我再定义展开。他将“BOSS”作为超越CEO、rapper、艺人、制作人等狭义标签的综合身份，强调自己始终是完整而连续的“SKY-HI”，反对对艺人进行简单分类及由此产生的偏见。文章还谈及“三年后东京巨蛋”宣言背后的使命感，以及他在BMSG事业逐渐步入正轨后，作为艺人回归纯粹创作与舞台表达的状态。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>SKY-HI、日高光启、BMSG、BE:FIRST、THE SUPER FLYERS、BFQ</strong>：专有名词、团体名及英文大小写须统一。</li><li><strong>BOSS / BOSSDOM</strong>：既是身份定位，也是巡演标题和精神理念，不宜简单译为“老板”或“老板统治”。</li><li><strong>CEO、社长、制作人、rapper、artist、idol</strong>：需区分职务、创作身份与行业分类，避免互相替代。</li><li><strong>「自分自身の再定義」</strong>：重点是重新塑造他者与自我对“SKY-HI”的认知，不只是“改变定位”。</li><li><strong>“偶像/艺人之争”</strong>：涉及日本娱乐行业语境，不宜按中文娱乐圈惯例强行归类。</li><li><strong>“东京巨蛋”宣言</strong>：既有临场冲动，也包含责任感和使命感，不能译成单纯的商业目标。</li><li><strong>“ゴミ箱に捨てられてきた夢”</strong>：具有被轻视、被抛弃的强烈情绪，须保留形象感。</li><li><strong>“因数分解”“ボタンを掛け違えた”</strong>：分别是自我剖析和长期错位的比喻，应避免机械直译。</li><li>语气在管理者的理性、艺术家的热情与访谈中的随意口语之间切换；“笑”“不知道为什么”“挺纯粹”等表达要保留自然感。</li><li>对“标签、偏见、逆偏见”的批判较尖锐，尤其“叩き潰したい”应体现强硬态度，但避免过度激烈或失真。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>以第一人称访谈为核心，保持口语化、坦率且有思辨性的表达；第三人称导语则采用出版物风格，客观、凝练、具有现场感。</li><li><strong>BOSS</strong>建议保留英文，并在首次出现时结合上下文解释为“广义上的领导者/核心人物”，不要固定译成“老板”。</li><li>将“社长身份、艺人身份、制作人身份彼此不可分割”的逻辑译清楚，这是全文的核心思想。</li><li>保留音乐现场的能量和娱乐性，如“空间演出技术”“舞台调度”“观众能量交换”“压倒性的表演”等专业表达。</li><li>“アイドル”和“アーティスト”可分别译为“偶像”和“艺人/艺术家”，但需根据段落保持术语一致。</li><li>“功名心もない”“谁都不会因此为难”等句子应译得克制自然，突出其非功利、纯粹创作的状态。</li><li>结尾“像刷牙一样日常”“真正有了出道感”应保留生活化比喻和余韵，不宜改写成抽象的职业总结。</li></ul>',6)])])}const d=r(o,[["render",s]]);export{p as __pageData,d as default};
